// ============================================================================
// src/lib/tools/expect-script-builder/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the Expect script builder
// (set "expect-script-builder/2026-10-27b").
//
// Three kinds, all run by verifyVectors():
//
// 1. ACCEPT vectors pin the whole result byte for byte: the script, the notes
//    (code, severity, details), the sections and their lines, and what the
//    script needs at run time. Each one covers a combination worth reading in
//    full, and the scripts of several were run with the real expect 5.45.4
//    against a fake device (the suite's runs 05 to 07, recorded in its notes).
//    The first one is the page's Example (D-83).
// 2. REJECT vectors pin the errors of input that cannot be built, one per
//    rule the validator applies.
// 3. The CLASS sweep builds every combination class of output (each transport
//    and authentication pair, each device profile with each enable and paging
//    choice (and with no paging choice where its default is not "off"), the
//    generic profile, the host fixed or from the command line,
//    each output mode, a logout command or a close) and runs each script
//    through the Expect script explainer's engine: every one must build and
//    must give no syntax error, no error and no warning. Notes are allowed (E5
//    on the Space that answers a more prompt, E12 on a script that writes only
//    to a file): they describe what the script does on purpose.
//
// Expected values were captured from build() on 2026-10-27 after each script
// was read line by line against expect(1) 5.45.4 and the device profiles.
//
// Set "b" (2026-10-27, PRIME's decision): by default a script leaves the
// device's configuration alone, so FortiOS with no paging choice answers
// --More-- instead of turning paging off (a global change). The two FortiOS
// vectors that turn paging off now ask for it explicitly, fortios-answer gains
// the note that nothing changes, fortios-default-answer pins the default, and
// the sweep also builds each profile whose default differs from "off" with no
// paging choice at all.
// ============================================================================

import { build, defaultPaging, type BuilderInput, type BuilderResult } from "./compute"; // the engine
import { run as explain } from "@/lib/tools/expect-script-explainer/compute"; // the explainer's engine, for the class sweep
import { DEVICE_PROFILES } from "@/content/expect/device-profiles"; // the profiles the sweep walks

/** The set's dated id: bump the letter whenever a vector or the engine changes. */
export const GOLDEN_VECTOR_SET_ID = "expect-script-builder/2026-10-27b";

/** The fields an accept or reject vector pins, in compact stable forms. */
export interface Pinned {
  /** Whether a script was built. */
  ok: boolean;
  /** Each error as "field code [params]". */
  errors: string[];
  /** Each note as "code severity [params]". */
  notes: string[];
  /** Each section as "id from-to". */
  sections: string[];
  /** What the script needs at run time. */
  needs: BuilderResult["needs"];
  /** The script, byte for byte. */
  script: string;
}

/** One vector: a name, what it covers, the input, and the pinned result. */
export interface Vector {
  /** Short stable name. */
  id: string;
  /** What it covers. */
  note: string;
  /** The input, exactly as the tool takes it (missing fields take the defaults). */
  input: Partial<BuilderInput>;
  /** The pinned result. */
  expect: Pinned;
}

/** Reduce a result to the pinned fields. */
export function pin(r: BuilderResult): Pinned {
  // Errors, notes and sections as short lines; needs and the script as they are.
  return {
    ok: r.ok, // built or not
    errors: r.errors.map((e) => `${e.field} ${e.code}${e.params ? " " + JSON.stringify(e.params) : ""}`), // why not
    notes: r.notes.map((n) => `${n.code} ${n.severity}${n.params ? " " + JSON.stringify(n.params) : ""}`), // what to know
    sections: r.sections.map((s) => `${s.id} ${s.from}-${s.to}`), // the parts
    needs: r.needs, // the run-time needs
    script: r.script, // the bytes
  };
}

