/** The page's Example (D-83): the first accept vector's input, verbatim. */
export const EXAMPLE: Partial<BuilderInput> = VECTORS[0].input;

/** The Example as an API request body (the OpenAPI example and the input detector's example). */
export const API_EXAMPLE = JSON.stringify({ transport: "ssh", host: "sw1.example.net", user: "netops", auth: "env", passwordVar: "DEVICE_PASSWORD", profile: "cisco-ios", commands: "show version" });

/**
 * Every combination class of builder output, as inputs: each transport and authentication pair (with
 * the variants that change ssh's command line), each device profile with each enable and paging choice
 * it allows (and the restore on or off where the setting outlives the session), the generic profile with
 * and without a paging command, the host fixed or from the command line (ssh and telnet), each output
 * mode, and a logout command or a close.
 */
export function combinationClasses(): Partial<BuilderInput>[] {
  // Transport and authentication.
  const access: Partial<BuilderInput>[] = [
    { transport: "ssh", auth: "key" }, // a key from the agent or ssh's defaults
    { transport: "ssh", auth: "key", keyFile: "keys/id_ed25519", port: "2222" }, // a key file, IdentitiesOnly, a port
    { transport: "ssh", auth: "env" }, // a password from the environment
    { transport: "ssh", auth: "ask", user: "" }, // a password asked for, no -l
    { transport: "telnet", auth: "env" }, // telnet, user name and password
    { transport: "telnet", auth: "ask" }, // telnet, password asked for
    { transport: "program", program: "cu -l /dev/ttyUSB0 -s 9600", auth: "none", user: "" }, // a program with no login
    { transport: "program", program: "console-client sw1", auth: "env", user: "" }, // a program asking for a password only
    { transport: "program", program: "console-client sw1", auth: "ask", user: "admin" }, // a program asking for a user name and a password
  ];
  // Device choices.
  const device: Partial<BuilderInput>[] = [];
  // Each profile.
  for (const p of DEVICE_PROFILES) {
    // The enable choices it allows.
    const enables: BuilderInput["enable"][] = p.privilege.model === "enable" ? (p.privilege.passwordPromptRegex ? ["no", "plain", "env", "ask"] : ["no", "plain"]) : ["no"];
    // The paging choices it allows.
    const pagings: BuilderInput["paging"][] = p.paging.morePrompt ? ["off", "answer"] : ["off"];
    // Every combination, with the restore on and off when paging is turned off.
    for (const enable of enables) for (const paging of pagings) for (const restorePaging of paging === "off" ? [true, false] : [true]) device.push({ profile: p.id, enable, paging, restorePaging });
    // No paging choice at all, where the profile's default is not "off" (FortiOS: answer, leaving the configuration alone).
    if (defaultPaging(p.id) !== "off") device.push({ profile: p.id });
  }
  // The generic profile, with and without a paging command.
  device.push({ profile: "generic", paging: "off", genericPagingCommand: "terminal length 0" }, { profile: "generic", paging: "none" });
  // The full product.
  const out: Partial<BuilderInput>[] = [];
  // Access by device by host source by output by ending.
  for (const a of access) for (const dv of device) for (const hostFromArgv of [false, true]) for (const output of ["screen", "file", "both"] as const) for (const logout of ["exit", ""]) {
    // A program has no host.
    if (a.transport === "program" && hostFromArgv) continue;
    // The class.
    out.push({ ...a, ...dv, hostFromArgv, output, logout, commands: "show version\nshow running-config" });
  }
  // All of them.
  return out;
}

/** What verifyVectors reports (the shape scripts/run-golden-vectors.mts reads). */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors and classes run. */
  total: number;
  /** Those that matched. */
  passed: number;
  /** Those that did not, with the first difference. */
  failures: { id: string; reason: string }[];
}

/** Run every vector and every class. */
export function verifyVectors(): VerifyReport {
  // Failures found.
  const failures: { id: string; reason: string }[] = [];
  // Accept and reject vectors, byte for byte.
  for (const v of [...VECTORS, ...REJECTS]) {
    // A throw is a failure too.
    try {
      // The result's pinned fields as text.
      const got = JSON.stringify(pin(build(v.input)));
      // The expected text.
      const want = JSON.stringify(v.expect);
      // Compare.
      if (got !== want) {
        // The first differing character.
        let k = 0;
        // Walk to it.
        while (k < got.length && got[k] === want[k]) k++;
        // Record.
        failures.push({ id: v.id, reason: `differs at ${k}: got ...${got.slice(Math.max(0, k - 40), k + 60)}... want ...${want.slice(Math.max(0, k - 40), k + 60)}...` });
      }
    } catch (e) {
      // The error.
      failures.push({ id: v.id, reason: `threw: ${(e as Error).message}` });
    }
  }
  // The classes.
  const classes = combinationClasses();
  // Each one through the explainer.
  classes.forEach((input, i) => {
    // Build.
    const r = build(input);
    // It must build.
    if (!r.ok) { failures.push({ id: `class-${i}`, reason: `not built: ${r.errors.map((e) => e.field + " " + e.code).join(", ")} for ${JSON.stringify(input)}` }); return; }
    // The explainer's reading.
    const e = explain({ script: r.script });
    // No syntax error, no error, no warning.
    if (e.syntaxError || e.counts.error > 0 || e.counts.warning > 0) failures.push({ id: `class-${i}`, reason: `explainer: ${e.findings.filter((f) => f.severity !== "info").map((f) => `${f.rule} ${f.severity} line ${f.line}`).join(", ") || "syntax " + e.syntaxError?.message} for ${JSON.stringify(input)}` });
  });
  // The report.
  const total = VECTORS.length + REJECTS.length + classes.length;
  // Out.
  return { setId: GOLDEN_VECTOR_SET_ID, total, passed: total - failures.length, failures };
}
